    public string source_path(Resource actor){var value=Get(actor.Get("values").AsGodotDictionary(),"transformation","");return value.VariantType==Variant.Type.String&&value.AsString().Length>0?ProjectSettings.GlobalizePath(value.AsString()).Replace('\\','/').SimplifyPath():"";}
