    public Settings load_asset(Settings assets,Resource actor)
    {
        string path=source_path(actor);if(path.Length==0)return new Settings{["document"]=default(Variant),["error"]="Choose a Transformation Image 2D asset."};ulong now=Time.GetTicksMsec();var entry=Get(assets,path,new Settings()).AsGodotDictionary();Resource? document=null;var weak=Get(entry,"document",default);if(weak.VariantType==Variant.Type.Object&&weak.AsGodotObject() is WeakRef reference)document=reference.GetRef().As<Resource>();string error=Get(entry,"error","").AsString();bool cached=entry.Count>0&&(document!=null||error.Length>0);if(cached&&now-Get(entry,"checked",0L).AsUInt64()<250)return new Settings{["document"]=ObjectValue(document),["error"]=error};ulong stamp=Godot.FileAccess.GetModifiedTime(path);if(cached&&stamp==Get(entry,"stamp",0L).AsUInt64()){entry["checked"]=now;return new Settings{["document"]=ObjectValue(document),["error"]=error};}
        error="Transformation asset is missing or invalid.";if(Godot.FileAccess.FileExists(path)&&(path.GetExtension().ToLowerInvariant() is "tres" or "res")){var loaded=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);document=loaded!=null&&ActorDataOperations.ScriptIs(loaded,"res://Workspaces/TransformationWorkspace/transformation_document.gd")?loaded:null;if(document!=null){var errors=document.Call("validate").AsStringArray();if(errors.Length==0)error="";else{error=errors[0];document=null;}}}
