    public string[] path_for(string id)=>new[]{"component_states",id};
    public string current(Resource actor,Resource item,double time)
    {
        var states=Get(actor.Get("values").AsGodotDictionary(),"component_states",new Settings()).AsGodotDictionary();string id=item.Get("id").AsString(),fallback=Get(states,id,item.Get("default_state_id")).AsString();if(!states.ContainsKey(id)&&_data.get_value(actor,"play_asset_animation",false).AsBool()){var keys=item.Call("sorted_keys").AsGodotArray();for(int index=0;index<keys.Count;index++){var key=keys[index].As<Resource>();if(index==0||key.Get("time").AsDouble()<=time)fallback=key.Get("state_id").AsString();else break;}}string value=_animation.sampled_value(actor,path_for(id),time,fallback).AsString();return item.Call("state_for_id",value).AsGodotObject()!=null?value:item.Get("default_state_id").AsString();
    }
    public Resource property_for(Resource item){var property=_properties.create(new StringName("state_"+item.Get("id").AsString()),"Current state",item.Get("default_state_id"),true);property.Get("options").AsGodotDictionary()["track_label"]="States / "+item.Get("title").AsString();return property;}
    public Settings capture(RefCounted model,Resource actor)=>new Settings{["actor"]=actor,["states"]=_data.copy_value(Get(actor.Get("values").AsGodotDictionary(),"component_states",new Settings())),["tracks"]=model.Call("animation_snapshot",actor)};
    public void restore(RefCounted model,GArray snapshots){foreach(var value in snapshots){var saved=value.AsGodotDictionary();var actor=saved["actor"].As<Resource>();actor.Get("values").AsGodotDictionary()[new StringName("component_states")]=_data.copy_value(saved["states"]);actor.Get("animation_previews").AsGodotDictionary().Clear();model.Call("restore_animation",actor,saved["tracks"]);}}
    public void choose(RefCounted model,Resource actor,Resource item,string state)
