on();
    }
    public Settings samples(Resource actor,Resource document,double time,Settings values)
    {
        var result=new Settings();var selected=Get(actor.Get("values").AsGodotDictionary(),"component_states",new Settings()).AsGodotDictionary();foreach(var value in document.Get("components").AsGodotArray()){var item=value.As<Resource>();string id=item.Get("id").AsString();var path=path_for(id);var track=_data.animation_track(actor,path);var preview=Get(actor.Get("animation_previews").AsGodotDictionary(),string.Join(" / ",path),new Settings()).AsGodotDictionary();if(track==null&&!selected.ContainsKey(id)&&preview.Count==0&&Get(values,"play_asset_animation",false).AsBool())continue;string state=Get(selected,id,item.Get("default_state_id")).AsString();var segment=new Settings{["from"]=state,["to"]=state,["weight"]=0.0,["key"]=default(Variant)};if(track!=null)segment=_tracks.transition_at(track,time,state);if(preview.Count>0)segment=new Settings{["from"]=preview["value"].AsString(),["to"]=preview["value"].AsString(),["weight"]=0.0,["key"]=default(Variant)};var a=item.Call("state_for_id",segment["from"].AsString()).As<Resource>();var b=item.Call("state_for_id",segment["to"].AsString()).As<Resource>();a??=item.Call("state_for_id",item.Get("default_state_id")).As<Resource>();b??=a;Resource outgoing=new KiwiTransformationKey();var authored=item.Call("sorted_keys").AsGodotArray();for(int index=0;index<authored.Count-1;index++){var left=authored[index].As<Resource>();var right=authored[index+1].As<Resource>();if(a!=null&&b!=null&&left.Get("state_id").AsString()==a.Get("id").AsString()&&right.Get("state_id").AsString()==b.Get("id").AsString()){outgoing=left.Call("copy_key").As<Resource>();break;}}int mode=Get(values,"morph_mode",0).AsInt32();if(mode>0)outgoing.Set("mode",new[]{"Auto Morph","Shape Morph","Guided Morph","Grow / Reveal","Step","Crossfade"}[Math.Clamp(mode-1,0,5)]);if(segment["key"].VariantType==Variant.Type.Object&&segment["key"].AsGodotObject() is Resource key&&key.Get("interpolation").AsInt32()==2)outgoing.Set("mode","Step");result[id]=new Settings{["a"]=ObjectValue(a),["b"]=ObjectValue(b),["t"]=outgoing.Get("mode").AsString()=="Step"?0.0:Math.Clamp(segment["weight"].AsDouble(),0,1),["key"]=outgoing};}return result;
    }
